/**
 * Canonical JSON and hashing, SPEC.md 3.1.
 *
 * This is the mirror of `contracts/ual/src/canonical.rs` and has to produce identical bytes
 * for identical input. `test-vectors/canonical.json` and `test-vectors/receipts.json` are
 * generated by the Rust side and verified here, so a divergence fails a test rather than
 * silently making receipts unverifiable in the browser.
 *
 * Rules:
 * - object keys sorted by byte order (not locale, not insertion order)
 * - no insignificant whitespace
 * - integers only, and only within the safe-integer range
 * - strings restricted to printable ASCII (0x20 to 0x7E)
 * - nulls are kept, never dropped
 * - arrays keep their order; they are sequences, not sets
 *
 * Because strings are printable ASCII, only `"` and `\` ever need escaping, which is why
 * Rust and JavaScript agree on the output without any further care.
 */

import { sha256Hex, utf8Bytes } from "./sha256.js";


/** Error codes match SPEC.md 4.4 so a local pre-check reports what the contract would. */
export type CanonicalErrorCode =
  | "E04_POLICY_NOT_CANONICAL"
  | "E05_POLICY_INVALID"
  | "E18_NON_ASCII";

export class CanonicalError extends Error {
  readonly code: CanonicalErrorCode;
  constructor(code: CanonicalErrorCode, detail: string) {
    super(`${code}: ${detail}`);
    this.name = "CanonicalError";
    this.code = code;
  }
}

/**
 * Largest integer a canonical JSON number may hold: 2^53 - 1.
 *
 * `JSON.parse` rounds anything past this to the nearest double, so a larger value would
 * canonicalise differently in Rust and JavaScript. SPEC.md 3.1 already carries money as
 * decimal strings and timestamps as nanosecond strings, so nothing real needs the range.
 */
export const MAX_SAFE_INTEGER = 9007199254740991;

export function isPrintableAscii(s: string): boolean {
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c < 0x20 || c > 0x7e) return false;
  }
  return true;
}

/** True if `s` is exactly 64 lowercase hex characters. */
export function isHex64(s: unknown): s is string {
  return typeof s === "string" && /^[0-9a-f]{64}$/.test(s);
}

/** Serialize to canonical form. Throws `CanonicalError` on anything the format forbids. */
export function canonical(value: unknown): string {
  const out: string[] = [];
  writeValue(value, out);
  return out.join("");
}

function writeValue(value: unknown, out: string[]): void {
  if (value === null) {
    out.push("null");
    return;
  }
  switch (typeof value) {
    case "boolean":
      out.push(value ? "true" : "false");
      return;
    case "number":
      writeNumber(value, out);
      return;
    case "string":
      writeString(value, out);
      return;
    case "bigint":
      // Deliberately refused. A bigint has no JSON number representation we could also
      // guarantee in the contract, and the format wants large values as strings anyway.
      throw new CanonicalError(
        "E05_POLICY_INVALID",
        "bigint is not a canonical JSON number; carry large values as decimal strings",
      );
    case "object":
      break;
    default:
      throw new CanonicalError(
        "E05_POLICY_INVALID",
        `${typeof value} cannot appear in canonical JSON`,
      );
  }

  if (Array.isArray(value)) {
    out.push("[");
    for (let i = 0; i < value.length; i++) {
      if (i > 0) out.push(",");
      writeValue(value[i], out);
    }
    out.push("]");
    return;
  }

  // undefined-valued keys are dropped by JSON.stringify but would be invisible here, so we
  // refuse them rather than let two different objects canonicalise the same way.
  const obj = value as Record<string, unknown>;
  const keys = Object.keys(obj);
  for (const k of keys) {
    if (obj[k] === undefined) {
      throw new CanonicalError(
        "E05_POLICY_INVALID",
        `key "${k}" is undefined; use null to mean absent`,
      );
    }
  }
  // Byte order. For printable ASCII this equals JavaScript's default string comparison, but
  // we sort on the bytes explicitly so the guarantee does not depend on that coincidence.
  keys.sort(compareByteOrder);

  out.push("{");
  for (let i = 0; i < keys.length; i++) {
    if (i > 0) out.push(",");
    writeString(keys[i], out);
    out.push(":");
    writeValue(obj[keys[i]], out);
  }
  out.push("}");
}

function compareByteOrder(a: string, b: string): number {
  // Keys are printable ASCII (enforced by writeString), so UTF-8 bytes are one per character
  // and a plain code-unit comparison is already byte order. Compared explicitly anyway, so the
  // guarantee does not rest on that coincidence, and without Buffer so this runs in a browser.
  const ab = utf8Bytes(a);
  const bb = utf8Bytes(b);
  const n = Math.min(ab.length, bb.length);
  for (let i = 0; i < n; i++) {
    if (ab[i] !== bb[i]) return ab[i]! - bb[i]!;
  }
  return ab.length - bb.length;
}

function writeNumber(n: number, out: string[]): void {
  if (!Number.isFinite(n)) {
    throw new CanonicalError("E05_POLICY_INVALID", `${n} is not a finite number`);
  }
  if (!Number.isInteger(n)) {
    throw new CanonicalError("E05_POLICY_INVALID", `${n} is a float; no floats anywhere`);
  }
  if (Math.abs(n) > MAX_SAFE_INTEGER) {
    throw new CanonicalError(
      "E05_POLICY_INVALID",
      `${n} is beyond 2^53 - 1; carry it as a decimal string`,
    );
  }
  // Object.is catches -0, which would serialize as "0" and lose a distinction the Rust side
  // does not have.
  out.push(Object.is(n, -0) ? "0" : String(n));
}

function writeString(s: string, out: string[]): void {
  if (!isPrintableAscii(s)) {
    throw new CanonicalError(
      "E18_NON_ASCII",
      `"${escapeForMessage(s)}" contains bytes outside printable ASCII`,
    );
  }
  out.push('"');
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch === '"') out.push('\\"');
    else if (ch === "\\") out.push("\\\\");
    else out.push(ch);
  }
  out.push('"');
}

function escapeForMessage(s: string): string {
  return s.replace(/[^\x20-\x7e]/g, (c) => `\\u${c.charCodeAt(0).toString(16).padStart(4, "0")}`);
}

/**
 * Parse JSON text that is supposed to be canonical, refusing anything the format forbids
 * *at the byte level* before parsing.
 *
 * This exists because of an asymmetry that cannot be papered over: Rust's `serde_json` keeps
 * the difference between `100` and `100.0`, and JavaScript does not. By the time
 * `JSON.parse` has run, `{"x":100.0}` and `{"x":100}` are the same object, so `canonical()`
 * alone would happily accept bytes the contract rejects with E05_POLICY_INVALID. A pre-check
 * that disagrees with the contract is worse than no pre-check, because it sends a
 * transaction that was always going to fail.
 *
 * So the number tokens are inspected in the raw text, where the decimal point is still
 * visible. Use this for anything that arrives as a string and has to survive the contract:
 * policy JSON above all, since `commit_policy` takes a string and compares bytes.
 */
export function parseCanonicalJson(text: string): unknown {
  assertNoFloatOrOversizedNumberSyntax(text);
  return JSON.parse(text);
}

/**
 * Scan JSON text for number tokens and refuse floats and integers past 2^53 - 1.
 * String contents are skipped, so a price written as the string "1.5" is fine.
 */
export function assertNoFloatOrOversizedNumberSyntax(text: string): void {
  const n = text.length;
  let i = 0;
  while (i < n) {
    const ch = text[i];

    if (ch === '"') {
      // Skip over a string literal, honouring backslash escapes, so that digits and dots
      // inside strings are not mistaken for numbers.
      i++;
      while (i < n) {
        if (text[i] === "\\") {
          i += 2;
          continue;
        }
        if (text[i] === '"') {
          i++;
          break;
        }
        i++;
      }
      continue;
    }

    if (ch === "-" || (ch >= "0" && ch <= "9")) {
      let j = i;
      if (text[j] === "-") j++;
      let isFloatSyntax = false;
      while (j < n) {
        const c = text[j];
        if (c >= "0" && c <= "9") {
          j++;
        } else if (c === ".") {
          isFloatSyntax = true;
          j++;
        } else if (c === "e" || c === "E") {
          isFloatSyntax = true;
          j++;
          if (j < n && (text[j] === "+" || text[j] === "-")) j++;
        } else {
          break;
        }
      }
      const token = text.slice(i, j);
      if (isFloatSyntax) {
        throw new CanonicalError(
          "E05_POLICY_INVALID",
          `${token} is written as a float; no floats anywhere, and no exponents`,
        );
      }
      if (!/^-?\d+$/.test(token)) {
        throw new CanonicalError("E05_POLICY_INVALID", `${token} is not an integer`);
      }
      const value = BigInt(token);
      const limit = BigInt(MAX_SAFE_INTEGER);
      if (value > limit || value < -limit) {
        throw new CanonicalError(
          "E05_POLICY_INVALID",
          `${token} is beyond 2^53 - 1; carry it as a decimal string`,
        );
      }
      i = j;
      continue;
    }

    i++;
  }
}

/**
 * Local pre-check for `commit_policy`: the bytes must already be their own canonical form.
 *
 * Returns nothing and throws on failure, with the code the contract would panic with, so a
 * caller can report the same error without spending a transaction. SPEC.md 8.1.
 */
export function assertPolicyBytesCanonical(policyJson: string): void {
  const parsed = parseCanonicalJson(policyJson);
  const recanonicalised = canonical(parsed);
  if (recanonicalised !== policyJson) {
    throw new CanonicalError(
      // The same code the contract panics with for this exact situation, SPEC.md 4.4.
      "E04_POLICY_NOT_CANONICAL",
      "policy bytes are not their own canonical form, so policyHash would be ambiguous",
    );
  }
}

// Re-exported so callers get hashing and canonical form from one module.
export { sha256Hex };

/** `sha256(canonical(value))`, lowercase hex. */
export function canonicalHash(value: unknown): string {
  return sha256Hex(canonical(value));
}

/**
 * Genesis head for a desk: `sha256("krexa-ual/v1:" + contractId + ":" + deskId)`.
 * SPEC.md 3.1.
 */
export function genesisHash(contractId: string, deskId: string): string {
  return sha256Hex(`krexa-ual/v1:${contractId}:${deskId}`);
}
